css='''
:root{--bg:#f3f1e9;--paper:#fffef9;--ink:#252a29;--muted:#69706b;--green:#dbe8ae;--dark:#1c2421;--line:#d9ddd1;--accent:#5a6e40;--warn:#855a30}*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:var(--bg);color:var(--ink);font:15px/1.65 Inter,Segoe UI,Arial,sans-serif}button,input,select{font:inherit}a{color:var(--accent)}button,a,input{touch-action:manipulation}button{cursor:pointer}header{background:var(--dark);color:#f6f7ec;padding:36px max(24px,calc((100vw - 1180px)/2));border-bottom:5px solid #b7ca85}.kicker{font-size:10px;letter-spacing:2px;color:#c3d3af;font-weight:700}.hero-row{display:flex;gap:32px;align-items:flex-end;justify-content:space-between}h1{font-size:clamp(30px,4.4vw,49px);font-weight:720;line-height:1.13;letter-spacing:-1.6px;margin:16px 0 17px}header p{max-width:780px;color:#bcc7bb;font-size:15px}.version{font-size:11px;white-space:nowrap;color:#bac8ad}.metrics{display:flex;flex-wrap:wrap;gap:25px;margin-top:23px}.metrics div{font-size:11px;color:#b9c3b4;border-left:1px solid #56644d;padding-left:12px}.metrics b{font-size:23px;color:#edf3d7;display:block;line-height:1.25}main{max-width:1228px;padding:28px 24px 55px;margin:auto}h2{font-size:25px;line-height:1.3;letter-spacing:-.5px;margin:0 0 18px}h3{font-size:17px;line-height:1.4;margin:8px 0 12px}p{margin:10px 0}.split{display:grid;grid-template-columns:1fr 1fr;gap:18px}.panel{background:var(--paper);border:1px solid var(--line);border-radius:9px;padding:25px;margin-bottom:20px}.panel-top{display:flex;align-items:center;gap:12px;margin-bottom:17px}.num{font-size:12px;letter-spacing:1px;background:#e8eddf;color:#586b3c;padding:5px 9px;border-radius:4px}.panel-top h2{margin:0}.download{display:inline-block;background:#293d2c;color:#fff!important;text-decoration:none;border:1px solid #293d2c;border-radius:5px;padding:10px 15px;font-size:13px;font-weight:650;margin:8px 7px 8px 0}.download.secondary{background:#f3f6e8;color:#415331!important;border-color:#c6d1b1}.label{font-size:11px;letter-spacing:.5px;text-transform:uppercase;color:#6c795d}.muted{color:var(--muted);font-size:13px}.notice{border-left:3px solid #b4864e;background:#f3ead9;padding:15px 18px;border-radius:0 5px 5px 0;font-size:13px;margin:17px 0}.fine{font-size:12px;color:#707967}.steps{padding-left:22px}.steps li{margin:12px 0}code{background:#edf1e5;color:#4b5d3d;border-radius:3px;padding:2px 5px;font:12px/1.6 Consolas,Menlo,monospace;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#edf1e6;border-left:3px solid #97a879;padding:15px;font:12px/1.7 Consolas,monospace;margin:13px 0}pre code{padding:0;background:none}.file-list{display:grid;gap:6px;margin:12px 0}.file-list span{display:block;font:11px/1.5 Consolas,monospace;background:#f1f4e9;padding:7px 10px;border-radius:4px;overflow-wrap:anywhere}details{border:1px solid #dce1d1;border-radius:5px;padding:10px 13px;margin:13px 0}summary{cursor:pointer;font-weight:650;font-size:13px}.copy,.play{border:1px solid #c0cdae;border-radius:4px;padding:6px 10px;background:#f0f5e6;color:#465b33;font-size:11px}.play{background:#293c2c;color:#fff;border-color:#293c2c}.copy:hover{background:#e1eacb}.toolbar{position:sticky;top:0;z-index:8;display:flex;gap:10px;align-items:center;background:#f3f1e9f5;padding:13px 0;margin-bottom:17px;border-bottom:1px solid #d9ddd1}.toolbar input{flex:1;min-width:100px;padding:10px 12px;border:1px solid #c6cfbb;border-radius:5px;background:var(--paper);font-size:13px}.toolbar select{padding:9px;border:1px solid #c6cfbb;border-radius:5px;background:var(--paper);font-size:12px;max-width:180px}.count{font-size:12px;color:#6b775e;white-space:nowrap}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:13px}.asset{background:var(--paper);border:1px solid var(--line);border-radius:7px;padding:17px;display:flex;flex-direction:column;gap:8px;min-width:0}.asset h3{font-size:15px;margin:0;line-height:1.45;overflow-wrap:anywhere}.asset .aid{font-size:11px;font-weight:700;letter-spacing:1px;color:#566e3d}.asset .desc{font-size:12px;color:#63705c;flex:1}.tags{display:flex;flex-wrap:wrap;gap:5px}.tag{font-size:10px;line-height:1.5;background:#edf1e5;padding:3px 6px;border-radius:3px;color:#597044}.tag.warn{background:#f4e5d1;color:#8c5829}.asset code{font-size:10px;background:#f2f3ea;display:block}.actions{display:flex;gap:6px;align-items:center;flex-wrap:wrap;margin-top:4px}.actions a{font-size:11px}.dest{font-size:11px;border-top:1px solid #e1e4d8;padding-top:8px;color:#4f6047}.recipe-text{font-size:11px;white-space:pre-wrap;max-height:320px;overflow:auto}.player{position:sticky;bottom:0;z-index:10;background:#202e24;color:#fff;border-radius:8px;padding:12px 16px;display:flex;align-items:center;gap:20px;margin-top:20px;box-shadow:0 -5px 20px #17201718}.player div{flex:1;font-size:12px}.player small{color:#aebda5;display:block}.player audio{max-width:400px;width:48%;height:35px}.flow{display:flex;flex-wrap:wrap;gap:7px;font-size:11px;align-items:center;margin:15px 0}.flow b{background:#eef2e5;padding:5px 9px;border:1px solid #d5dec8;border-radius:4px}.flow i{font-style:normal;color:#93a284}footer{font-size:12px;color:#727b69;border-top:1px solid var(--line);padding:19px 24px;max-width:1228px;margin:auto}.toast{position:fixed;bottom:20px;right:20px;z-index:100;background:#31462e;color:#fff;border-radius:5px;padding:10px 15px;font-size:12px;opacity:0;pointer-events:none}.toast.show{opacity:1}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:9px;border:1px solid #d8decd;text-align:left;vertical-align:top}th{background:#ecf1e2}*:focus-visible{outline:2px solid #ac7843;outline-offset:3px}@media(max-width:950px){.grid{grid-template-columns:repeat(2,1fr)}.split{grid-template-columns:1fr}.hero-row{display:block}.version{margin-top:10px}}@media(max-width:600px){body{font-size:14px}header{padding:25px 19px}main{padding:20px 15px 40px}.panel{padding:18px}.grid{grid-template-columns:1fr}.metrics{gap:16px}.metrics b{font-size:21px}.toolbar{flex-wrap:wrap}.toolbar input{width:100%;flex-basis:100%}.player{display:block}.player audio{width:100%;max-width:none;margin-top:7px}.panel-top h2{font-size:22px}h1{letter-spacing:-1px}}@media print{header{background:white;color:black;padding:0;border-bottom:2px solid #555}header p,.version,.metrics div,.metrics b{color:#333}.toolbar,.player,.copy,.play,.toast,.download{display:none!important}body{background:white;font-size:10pt}.split,.grid{display:block}.panel,.asset{break-inside:avoid;margin:10px 0}.panel{border:none;padding:0}.asset{padding:10px}main{padding:15px 0}.notice{background:#eee}details{display:none}footer{padding:12px 0}}
'''
js=r'''
const audioData=JSON.parse(document.getElementById('audio-data').textContent||'{}');
const metaData=JSON.parse(document.getElementById('meta-data').textContent||'{}');
const player=document.getElementById('audio-player'),plabel=document.getElementById('play-label');
let noticeTimer;
function notify(s){const n=document.getElementById('toast');n.textContent=s;n.classList.add('show');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>n.classList.remove('show'),2200);}
async function copyText(text){try{await navigator.clipboard.writeText(text);notify('Скопировано');}catch(e){const t=document.createElement('textarea');t.value=text;t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();let ok=false;try{ok=document.execCommand('copy');}catch(e){}t.remove();if(ok)notify('Скопировано');else{const box=document.getElementById('manual-copy');box.hidden=false;box.value=text;box.focus();box.select();notify('Текст выделен — нажми Ctrl+C / Cmd+C');}}}
document.querySelectorAll('[data-copy-target]').forEach(b=>b.addEventListener('click',()=>copyText(document.getElementById(b.dataset.copyTarget).textContent)));
document.querySelectorAll('[data-asset]').forEach(b=>b.addEventListener('click',()=>{const a=metaData[b.dataset.asset];copyText('Для текущей песни рассмотрим '+a.id+'.\nФайл: PART_2_STUDIO_ASSETS/'+a.path+'\nТип: '+a.kind+'; роль: '+a.role+'\nЭто файл в моей локальной библиотеке, не обязательно прикреплённое здесь аудио. Объясни куда его импортировать или как применить, согласуй BPM/key с песней, дай следующий шаг. Не делай вид, что уже прослушал или загрузил его в мой проект.');}));
document.querySelectorAll('[data-play]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.play;if(!audioData[id])return;player.src='data:audio/wav;base64,'+audioData[id];plabel.textContent=(b.dataset.label||id);player.play().catch(()=>notify('Нажми Play в плеере'));}));
const search=document.getElementById('search'),filter=document.getElementById('filter');
function applyFilter(){if(!search||!filter)return;const q=search.value.trim().toLowerCase(),k=filter.value;let n=0;document.querySelectorAll('.asset').forEach(c=>{const show=(!q||c.dataset.search.includes(q))&&(!k||c.dataset.group===k);c.hidden=!show;if(show)n++;});document.getElementById('result-count').textContent=n+' / '+document.querySelectorAll('.asset').length;}
if(search)search.addEventListener('input',applyFilter);if(filter)filter.addEventListener('change',applyFilter);applyFilter();
'''

def player_html():
 return '<div class="player"><div><span id="play-label">Выбери материал для короткого предпрослушивания</span><small>Preview: mono / PCM16 / 22.05 kHz / максимум 5 с. Для работы — оригинальный WAV.</small></div><audio id="audio-player" controls preload="none"></audio></div>'

mrender={'M01':'L04','M02':'L03','M03':'L09','M04':'L08','M05':'L11','M06':'L05','M07':'L10','M09':'L01','M10':'L02'}
role_alias={'Keys':'клавиши пианино tines electric piano','Bass':'бас саб sub','Drums':'барабаны kick snare hat','Percussion':'перкуссия стрекот','FX':'эффекты ток электричество','Pad':'пад подложка атмосфера','Scene':'эскиз микс референс','Synth string':'щипки синт гитара'}

def card(a,links=True):
 aid=a['id'];kind=a['kind'];group='recipe' if kind=='recipe' else ('midi' if kind in ['midi','gm_drum_midi'] else a['role'])
 desc=a.get('description_ru','')
 search=(aid+' '+a['file']+' '+kind+' '+a['role']+' '+desc+' '+role_alias.get(a['role'],'')+' '+str(a.get('key',''))).lower()
 tags=[kind.upper(),a['role']]
 if a.get('bpm'):tags.append(str(a['bpm'])+' BPM')
 if a.get('key'):tags.append(a['key'])
 if a.get('bars'):tags.append(str(a['bars'])+' bars')
 if a.get('duration_s'):tags.append(f"{a['duration_s']:.2f} s")
 badge=''
 if kind=='gm_drum_midi':badge='<span class="tag warn">DAW + drum mapping</span>'
 if kind=='scene':badge='<span class="tag warn">Полный эскиз, НЕ stem</span>'
 if kind=='recipe':badge='<span class="tag warn">Текст, НЕ preset</span>'
 pr=aid if aid in audio else mrender.get(aid)
 play=''
 if pr:
  label=aid+' — '+a['file']
  if pr!=aid:label+=' | слушаем связанный WAV '+pr+', не звук внутри MIDI'
  play=f'<button class="play" data-play="{pr}" data-label="{esc(label,quote=True)}">▶ '+('Рендер '+pr if pr!=aid else 'Слушать')+'</button>'
 original=f'<a href="{esc(a["path"],quote=True)}" download>Оригинал файла</a>' if links else ''
 details=''
 if kind=='recipe':details='<details><summary>Прочитать рецепт</summary><div class="recipe-text">'+esc((P2/a['path']).read_text())+'</div></details>'
 dest=a['destination']
 return f'''<article class="asset" id="asset-{aid}" data-group="{esc(group,quote=True)}" data-search="{esc(search,quote=True)}"><span class="aid">{aid}</span><h3>{esc(a['file'])}</h3><div class="tags">{''.join('<span class="tag">'+esc(t)+'</span>' for t in tags)}{badge}</div><div class="desc">{esc(desc)}</div><code>{esc(a['path'])}</code><div class="dest">Куда: {esc(dest)}</div><div class="actions">{play}<button class="copy" data-asset="{aid}">Запрос для Gemini</button>{original}</div>{details}</article>'''

def page(title,header,body,data,metas,foot):
 return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><style>{css}</style></head><body>{header}<main>{body}<textarea id="manual-copy" hidden aria-label="Текст для ручного копирования" style="width:100%;height:130px"></textarea></main><footer>{foot}</footer><div id="toast" class="toast" role="status"></div><script type="application/json" id="audio-data">{json.dumps(data)}</script><script type="application/json" id="meta-data">{json.dumps(metas,ensure_ascii=True)}</script><script>{js}</script></body></html>'''

head='''<header><div class="kicker">DARK PRODUCTION KIT / PART 02</div><div class="hero-row"><div><h1>Найди звук.<br>Знай, куда его поставить.</h1><p>Оригинальные синтетические исходники, редактируемые MIDI и рецепты под твой dark art-pop, indie/post-punk и industrial-organic звук. Без чужих Splice-сэмплов и без вокальных клонов.</p></div><div class="version">Версия · 11.09.2026</div></div><div class="metrics"><div><b>48</b>WAV · 48 kHz / 24-bit</div><div><b>12</b>MIDI · ноты и ритм</div><div><b>10</b>карточек-рецептов</div><div><b>3</b>связанные палитры</div></div></header>'''
options=['<option value="">Вся библиотека</option>']
for x,label in [('Keys','Клавиши'),('Bass','Бас'),('Drums','Ударные'),('Percussion','Перкуссия'),('FX','Электрические FX'),('Pad','Пады'),('Synth string','Синтетические щипки'),('Scene','Полные эскизы'),('midi','MIDI'),('recipe','Рецепты')]:options.append(f'<option value="{x}">{label}</option>')
body='''<section class="panel"><h2>Сначала выбери роль, не всё сразу</h2><p><b>Быстрый Dm96-старт:</b> M01 + R03 для keys, M02 + R01 для sub, L01 для drums, L02 для редкой перкуссии, F02 для электрического акцента. Или L04/L03 вместо соответствующих MIDI, если нужен уже готовый звук.</p><div class="notice">WAV → Audio. Melodic MIDI → MIDI + инструмент. M09/M10 → DAW с drum mapping. R*.txt → читать, не импортировать как preset. S01–S03 → полный инструментальный эскиз, не отдельная партия.</div><p class="muted">Кнопка «Запрос для Gemini» копирует точный ID/путь и вопрос, как применить материал в текущей песне. Она не загружает аудио в Gemini. Каталог в Knowledge уже знает эти имена.</p></section>'''
body+='<div class="toolbar"><input id="search" type="search" placeholder="ID, инструмент, тональность, слово…" aria-label="Поиск по библиотеке"><select id="filter" aria-label="Тип материала">'+''.join(options)+'</select><span class="count" id="result-count"></span></div>'
body+='<div class="grid">'+''.join(card(x) for x in assets)+'</div>'+player_html()
body+='''<details><summary>Полная инструкция по библиотеке</summary>'''+md.render((P2/'00_READ_ME_FIRST.md').read_text())+'</details>'
(P2/'BROWSE_LIBRARY.html').write_text(page('Библиотека Dark Production — 70 материалов',head,body,audio,by,'Оригиналы лежат в AUDIO/MIDI/RECIPES этой распакованной папки. Для аудиоработы используй полные WAV, а не уменьшенное preview. Техническая проверка не равна прослушиванию в твоём аккаунте Suno.'))

boot=(P1/'GEM_INSTRUCTIONS.txt').read_text();starter=(P1/'START_NEW_SONG.txt').read_text();tests=(P1/'CHECK_GEM_SETUP.txt').read_text()
kfiles=[p.name for p in sorted((P1/'KNOWLEDGE').glob('*.txt'))]
header='''<header><div class="kicker">GEMINI × SUNO V6 × ТВОЙ VOICE</div><div class="hero-row"><div><h1>Твой продюсер.<br>Два пакета — одна система.</h1><p>Первый пакет учит Gemini помогать с каждой песней. Второй даёт реальные звуки, MIDI и понятную карту: какой файл, зачем и в какой слот.</p></div><div class="version">Готовый комплект · 11.09.2026</div></div><div class="metrics"><div><b>6</b>файлов Knowledge</div><div><b>1</b>готовая инструкция Gem</div><div><b>60</b>музыкальных исходников</div><div><b>10</b>прикладных рецептов</div></div></header>'''
main='''<div class="split"><section class="panel"><div class="panel-top"><span class="num">01</span><h2>Для Gemini</h2></div><p>Готовая роль помощника, база v6/Studio, промпты, свой Voice, финишинг, поиск звуков и паспорт каждой песни.</p><a class="download" href="PART_1_GEMINI.zip" download>Часть 1 · Gemini ZIP</a><p class="muted">Сначала распаковать. Загружать шесть TXT из KNOWLEDGE; инструкцию вставить отдельно в Instructions.</p></section><section class="panel"><div class="panel-top"><span class="num">02</span><h2>Для музыки</h2></div><p>48 WAV, 12 MIDI, 10 рецептов и браузер-каталог с прослушиванием. Карта всей библиотеки уже включена в Knowledge.</p><a class="download" href="PART_2_STUDIO_ASSETS.zip" download>Часть 2 · Studio Assets ZIP</a><p class="muted">Распаковать на компьютер. Открыть BROWSE_LIBRARY.html. WAV/MIDI импортировать в музыкальный проект, не весь ZIP в Gemini.</p></section></div>'''
main+='''<section class="panel"><h2>Установка Gem — один раз</h2><ol class="steps"><li>Открой <a href="https://gemini.google.com/" target="_blank" rel="noopener">gemini.google.com</a> → <b>Gems / Explore Gems → New Gem</b>. Выбери обычный custom Gem, не Labs mini-app.</li><li>Назови его, например <b>«Мой продюсер — Suno / Dark Studio»</b>.</li><li>Скопируй готовую инструкцию ниже в поле <b>Instructions</b>.</li><li>В <b>Knowledge → Add files → Upload</b> добавь эти шесть файлов из части 1:<div class="file-list">'''+''.join('<span>'+esc(f)+'</span>' for f in kfiles)+'''</div></li><li>Нажми <b>Save</b>. Preview сам по себе не сохраняет Gem. Отправь контрольный запрос ниже.</li></ol><button class="copy" data-copy-target="boot">Копировать всю инструкцию Gem</button><details><summary>Показать инструкцию для поля Instructions</summary><pre id="boot">'''+esc(boot)+'''</pre></details><p class="fine">Это адаптация официального процесса Google: <a href="https://support.google.com/gemini/answer/15235603?hl=en" target="_blank" rel="noopener">[1]</a>. Не нужно добавлять старые версии наших баз вместе с новой: они могут противоречить текущим правилам.</p></section>'''
main+='''<div class="split"><section class="panel"><h2>Каждая песня — новый чат</h2><div class="flow"><b>Твоя задача</b><i>→</i><b>Gemini: решение + prompt</b><i>→</i><b>Ты: selection в Studio</b><i>→</i><b>Suno: результат</b></div><p>Один Gem, разные разговоры по песням. Сохраняй паспорт, approved файлы и настройки. Для продолжения в новом чате прикрепи последний паспорт.</p><button class="copy" data-copy-target="starter">Копировать старт песни</button><details><summary>Стартовое сообщение</summary><pre id="starter">'''+esc(starter)+'''</pre></details></section><section class="panel"><h2>Проверь помощника</h2><p>Он должен знать свой Voice по умолчанию, различать Audio/MIDI/рецепты, не отправлять Splice в AI автоматически и не утверждать, что уже изменил твой проект.</p><button class="copy" data-copy-target="tests">Копировать проверку Gem</button><details><summary>Проверка и ожидаемые ответы</summary><pre id="tests">'''+esc(tests)+'''</pre></details><p class="muted">Эти тесты нужно выполнить в твоём аккаунте. Здесь мы проверили файлы и структуру комплекта, а не поведение твоего Gem.</p></section></div>'''
